def pinned(image):
    """(FROM reference pinned by digest, digest), or (None, None) when the tag was removed."""
    repository, _, tag = image.rpartition(":")
    if repository != IMAGE_DIGESTS["repository"]:
        raise ValueError(f"unexpected image repository: {image}")
    if tag in IMAGE_DIGESTS["removed_tags"]:
        return None, None
    digest = IMAGE_DIGESTS["digests"].get(tag)
    if not digest:
        raise ValueError(f"no pinned digest for {image}")
    return f"{repository}@{digest}", digest


